from __future__ import annotations

__doc__ = """
MATLAB/Octave code generation for Phoenix libraries.

This backend supports two modes:

- pure MATLAB mode, where instruction trees are lowered directly to vectorized
  MATLAB code,
- wrapper mode, where a selected compiled backend is generated first and a
  MATLAB class wraps the compiled entry points through MEX.

Pure mode follows the NumPy backend closely and uses array selectors plus
``accumarray``-based scatter accumulation instead of Python-style loops.
Wrapper mode mirrors the MEX-oriented design used by the dedicated compiled
backends and integrates with the makefile layer.
"""

