class MLNumeric(Numeric):
    """MATLAB numeric wrapper."""


class MLLibRoutineVariable(LibRoutineVariable):
    """Shared MATLAB-side variable behaviour."""

    DTYPE_LOOKUP = {
        "f64": "double",
        "f32": "single",
        "i64": "int64",
        "i32": "int32",
    }

    def lookup_dtype(self, dtype):
        if dtype in type(self).DTYPE_LOOKUP:
            return type(self).DTYPE_LOOKUP[dtype]
        raise ValueError(f"Unknown dtype: {dtype}")

    def expr_at(self, offset_string):
        return f"{self.name}(({offset_string}) + 1)"

    def get_zero_value(self):
        return f"cast(0, '{self.lookup_dtype(self.dtype)}')"

    def get_definition_lines(self):
        if self.is_scalar:
            yield f"{self._name} = {self.get_zero_value()};"
            return
        yield (
            f"{self._name} = zeros({self._size}, 1, '{self.lookup_dtype(self.dtype)}');"
        )

    def generate_tozero_lines(self):
        zero_value = self.get_zero_value()
        if self.is_scalar:
            yield f"{self.expr()} = {zero_value};"
            return
        yield f"{self.name}(:) = {zero_value};"


class MLLocalVariable(MLLibRoutineVariable, LibRoutineLocalVariable):
    """Local MATLAB variable."""


class MLDummyVariable(MLLibRoutineVariable):
    """Base class for MATLAB routine arguments."""

    _intent = None

    def as_argument_declaration(self):
        return self._name

    def get_definition_lines(self):
        return
        yield

    def expr(self):
        if self.is_scalar and type(self)._intent in {"WO", "RW"}:
            return f"{self.name}(1)"
        return super().expr()


class MLInputVariable(MLDummyVariable, LibRoutineInputVariable):
    """Read-only MATLAB routine argument."""

    _intent = "RO"


class MLOutputVariable(MLDummyVariable, LibRoutineOutputVariable):
    """Write-only MATLAB routine argument."""

    _intent = "WO"


class MLInOutVariable(MLDummyVariable, LibRoutineInOutVariable):
    """Read-write MATLAB routine argument."""

