class MLMultiFrameExpandContainer(MultiFrameExpandContainer):
    """Vectorized multiframe expansion for MATLAB selectors."""

    DEFAULT_LOCAL_VARIABLE_CLASS = MLLocalVariable
    INDENT_BODY = False

    def generate_head_containers(self):
        if self._multiframe_variable is None:
            return
        expr = self._multiframe_variable.expr()
        end_value = self._max_value - 1
        yield from self.codelines_from_text(
            f"{expr} = int64(({self._min_value}:{end_value}).');"
        )

    def generate_foot_containers(self):
        return
        yield


class MLIntCombineExpandContainer(IntCombineExpandContainer):
    """Vectorized combined multiframe expansion for MATLAB selectors."""

    DEFAULT_LOCAL_VARIABLE_CLASS = MLLocalVariable
    INDENT_BODY = False

    def generate_head_containers(self, **_):
        expr = self._multiframe_variable.local.expr()
        first = self._first.local.expr()
        second = self._second.local.expr()
        grid_name = f"{self._multiframe_variable.local.name}_grid"
        combine_expr = (
            f"reshape({second}, [], 1) * {self._first.max_value}"
            f" + reshape({first}, 1, [])"
        )
        if self._multiframe_variable.min_value:
            combine_expr += f" + {self._multiframe_variable.min_value}"
        yield from self.codelines_from_text(f"{grid_name} = {combine_expr};")
        yield from self.codelines_from_text(f"{expr} = {grid_name}(:);")
        yield from self.codelines_from_text(
            f"{expr} = {expr}({expr} < {self._multiframe_variable.max_value});"
        )

    def generate_foot_containers(self, **_):
        return
        yield


class MLScatterAffineContainer(CodeLine):
    """Vectorized affine accumulation using ``accumarray``."""

    def __init__(self, y_var, y_offsets, a, x, b, *, context, **params):
        super().__init__(context=context, **params)
        self._y_var = y_var
        self._y_offsets = y_offsets
        self._a = a
        self._x = x
        self._b = b
        self.requires(y_var)
        self.requires(x)
        self.requires(a)
        self.requires(b)

    @staticmethod
    def _offset_expression(offsets) -> str:
        return " + ".join(
            ValueAt.process_offsets(
                *offsets,
                simplify=True,
                allow_strings=True,
            )
        )

    def construct_code_lines(self, **_):
        library_name = self.context.library.libname
        offset_expr = self._offset_expression(self._y_offsets)
        expr = f"{self._a.expr()} * {self._x.expr()} + {self._b.expr()}"
        yield (
            f"{self._y_var.expr()} = {library_name}.scatter_add("
            f"{self._y_var.expr()}, ({offset_expr}) + 1, {expr});"
        )


class MLScatterBilinearContainer(CodeLine):
    """Vectorized bilinear accumulation using ``accumarray``."""

    def __init__(self, y_var, y_offsets, a, u, v, *, context, **params):
        super().__init__(context=context, **params)
        self._y_var = y_var
        self._y_offsets = y_offsets
        self._a = a
        self._u = u
        self._v = v
        self.requires(y_var)
        self.requires(u)
        self.requires(v)
        self.requires(a)

    @staticmethod
    def _offset_expression(offsets) -> str:
        return " + ".join(
            ValueAt.process_offsets(
                *offsets,
                simplify=True,
                allow_strings=True,
            )
        )

    def construct_code_lines(self, **_):
        library_name = self.context.library.libname
        offset_expr = self._offset_expression(self._y_offsets)
        expr = f"{self._a.expr()} * {self._u.expr()} * {self._v.expr()}"
        yield (
            f"{self._y_var.expr()} = {library_name}.scatter_add("
            f"{self._y_var.expr()}, ({offset_expr}) + 1, {expr});"
        )


class MLRoutineContainer(RoutineContainer):
    """MATLAB routine container used in pure mode."""

    INDENT_BODY = True
    INPUT_VARIABLE_CLASS = MLInputVariable

    def get_signature(self):
        inputs = []
        outputs = []
        for variable in self.get_argument_variables():
            if variable.status & variable.STATUS_INPUT:
                inputs.append(variable.as_argument_declaration())
            if variable.status & variable.STATUS_OUTPUT:
                outputs.append(variable.name)
        if outputs:
            return (
                f"function [{', '.join(outputs)}] = {self.name}"
                f"({', '.join(inputs)})"
            )
        return f"function {self.name}({', '.join(inputs)})"

    def generate_head_containers(self, **_):
        yield from self.codelines_from_text(self.get_signature())

    def generate_prmb_containers(self, **kwargs):
        local_variables = list(self.get_local_variables())
        if local_variables:
            yield from self.comment_from_text("LOCAL") or []
            for variable in local_variables:
                yield DefinitionLines(variable, context=self.context, **kwargs)
            yield from self.codelines_from_text("")

    def generate_foot_containers(self, **_):
        yield from self.codelines_from_text("end")


