class MatlabComputeResource(ComputeResource):
    """Compute resource that vectorizes multiframes for MATLAB output."""

    DEFAULT_LOCAL_VARIABLE_CLASS = MLLocalVariable

    def create_mfe_container(
        self,
        *,
        context,
        local_variable_capture,
        name=None,
        loop_container=None,
        loop_capture=None,
    ) -> None | MultiFrameExpandContainer:
        del name, loop_container, loop_capture
        return MLMultiFrameExpandContainer(
            context=context,
            local_variable_capture=local_variable_capture,
        )

    def create_combine_container(
        self,
        first,
        second,
        *,
        context,
        local_variable_capture,
        name=None,
        loop_container=None,
        loop_capture=None,
    ) -> None | MultiFrameExpandContainer:
        del name, loop_container, loop_capture
        return MLIntCombineExpandContainer(
            first,
            second,
            context=context,
            local_variable_capture=local_variable_capture,
        )


class MatlabBuilder(PyBuilder, identifier="MATLAB"):
    """MATLAB builder with optional compiled-backend selector utilities."""

    BACKEND_LIBRARY_LOOKUP = {
        "C": CLibrary,
        "FORTRAN": FortranLibrary,
    }

    @staticmethod
    def normalize_backend_builder(backend_builder):
        """Normalize backend builder selectors to a builder class or ``None``."""
        if backend_builder is None:
            return None
        if isinstance(backend_builder, Builder):
            return type(backend_builder)
        if isinstance(backend_builder, type):
            if issubclass(backend_builder, Builder):
                return backend_builder
        raise TypeError(
            "backend_builder must be None, a Builder instance, or a Builder subclass"
        )

    @classmethod
    def identify_backend(cls, backend):
        """Return ``None``, ``C`` or ``FORTRAN`` for a backend selector."""
        if backend is None:
            return None
        if isinstance(backend, CLibrary):
            return "C"
        if isinstance(backend, FortranLibrary):
            return "FORTRAN"
        backend_builder = cls.normalize_backend_builder(backend)
        if backend_builder is None:
            return None
        if issubclass(backend_builder, CBuilder):
            return "C"
        if issubclass(backend_builder, FortranBuilder):
            return "FORTRAN"
        raise ValueError(
            f"unsupported MATLAB backend builder: {backend_builder}"
        )

    @classmethod
    def create_backend_library(
        cls,
        plain_name,
        *,
        backend_builder=None,
        build_hash=None,
    ):
        """Create the compiled backend library selected for MATLAB wrapping."""
        kind = cls.identify_backend(backend_builder)
        if kind is None:
            return None
        library_class = cls.BACKEND_LIBRARY_LOOKUP[kind]
        return library_class(plain_name, build_hash=build_hash)

    def create_libroutine_variable(
        self,
        *,
        name,
        dtype,
        status,
        size,
        assignment=None,
        namespace=None,
        **kwargs,
    ):
        if status & LibRoutineVariable.STATUS_BUFFER:
            return MLBufferVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        status = status & 3
        if status == LibRoutineVariable.STATUS_INPUT:
            return MLInputVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        if status == LibRoutineVariable.STATUS_OUTPUT:
            return MLOutputVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        if status == LibRoutineVariable.STATUS_INOUT:
            return MLInOutVariable(
                name=name,
                dtype=dtype,
                size=size,
                assignment=assignment,
                namespace=namespace,
                **kwargs,
            )
        return super().create_libroutine_variable(
            name=name,
            dtype=dtype,
            status=status,
            size=size,
            namespace=namespace,
            **kwargs,
        )

    def create_local_variable(
        self, name, *, dtype, size=None, namespace=None, **kwargs
    ):
        return MLLocalVariable(
            name=name,
            dtype=dtype,
            size=size,
            namespace=namespace,
            **kwargs,
        )

    def create_external_array(self, *args, context, **kwargs):
        return Builder.create_external_array(
            self,
            *args,
            context=context,
            local_class=MLLocalVariable,
            constant_class=MLConstant,
        )

    def as_numeric(self, variable):
        return MLNumeric(variable)

    def handle_affine_instruction(self, instruction, context, buildargs):
        del buildargs
        instruction_dict = instruction.apply_environment(
            context.environment
        ).contribute_to_dict()

        tgt0 = instruction_dict.get("tgt0")
        src0 = instruction_dict.get("src0")
        alpha = instruction_dict.get("alpha", 1)
        beta = instruction_dict.get("beta", 0)

        x_var_real = context.namespace.find_assignment(
            type(src0), "real", exception_not_existing=False
        )
        x_var_imag = context.namespace.find_assignment(
            type(src0), "imag", exception_not_existing=False
        )
        y_var_real = context.namespace.find_assignment(
            type(tgt0), "real", exception_not_existing=False
        )
        y_var_imag = context.namespace.find_assignment(
            type(tgt0), "imag", exception_not_existing=False
        )

        x_var_offs = src0.offsets
        y_var_offs = tgt0.offsets
        a_real = self.wrap_lrv(alpha.real)
        a_imag = self.wrap_lrv(alpha.imag)
        b_real = self.wrap_lrv(beta.real)
        b_imag = self.wrap_lrv(beta.imag)

        combinations = [
            (y_var_real, a_real, x_var_real, b_real, 1),
            (y_var_real, a_imag, x_var_imag, b_real, -1),
            (y_var_imag, a_real, x_var_imag, b_imag, 1),
            (y_var_imag, a_imag, x_var_real, b_imag, 1),
        ]

        hook = HookContainer(context=context)
        first_real = True
        first_imag = True
        for y_var, a_val, x_var, b_val, sign in combinations:
            ret = self.check_relevance(y_var, a_val, x_var, b_val, hook=hook)
            if not ret:
                continue
            if y_var is y_var_real and not first_real:
                b_val = self.wrap_lrv(0.0)
            if y_var is y_var_imag and not first_imag:
                b_val = self.wrap_lrv(0.0)
            yield MLScatterAffineContainer(
                y_var,
                y_var_offs,
                a_val * sign,
                x_var.at(*x_var_offs),
                b_val,
                context=context,
            )
            if y_var is y_var_real:
                first_real = False
            else:
                first_imag = False

        yield CodeLine("", context=context)

    def handle_bilinear_instruction(self, instruction, context, buildargs):
        del buildargs
        instruction_dict = instruction.apply_environment(
            context.environment
        ).contribute_to_dict()

        tgt0 = instruction_dict.get("tgt0")
        src0 = instruction_dict.get("src0")
        src1 = instruction_dict.get("src1")
        alpha = instruction_dict.get("alpha")

        u_var_real = context.namespace.find_assignment(
            type(src0), "real", exception_not_existing=False
        )
        u_var_imag = context.namespace.find_assignment(
            type(src0), "imag", exception_not_existing=False
        )
        v_var_real = context.namespace.find_assignment(
            type(src1), "real", exception_not_existing=False
        )
        v_var_imag = context.namespace.find_assignment(
            type(src1), "imag", exception_not_existing=False
        )
        y_var_real = context.namespace.find_assignment(
            type(tgt0), "real", exception_not_existing=False
        )
        y_var_imag = context.namespace.find_assignment(
            type(tgt0), "imag", exception_not_existing=False
        )

        u_var_offs = src0.offsets
        v_var_offs = src1.offsets
        y_var_offs = tgt0.offsets
        a_real = self.wrap_lrv(alpha.real)
        a_imag = self.wrap_lrv(alpha.imag)

        hook = HookContainer(context=context)
        combinations = [
            (y_var_real, a_real, u_var_real, v_var_real, +1),
            (y_var_real, a_real, u_var_imag, v_var_imag, -1),
            (y_var_real, a_imag, u_var_imag, v_var_real, -1),
            (y_var_real, a_imag, u_var_real, v_var_imag, -1),
            (y_var_imag, a_real, u_var_imag, v_var_real, +1),
            (y_var_imag, a_real, u_var_real, v_var_imag, +1),
            (y_var_imag, a_imag, u_var_real, v_var_real, +1),
            (y_var_imag, a_imag, u_var_imag, v_var_imag, -1),
        ]

        for y_var, a_val, u_var, v_var, sign in combinations:
            ret = self.check_relevance(y_var, a_val, u_var, v_var, hook=hook)
            if not ret:
                continue
            yield MLScatterBilinearContainer(
                y_var,
                y_var_offs,
                sign * a_val,
                u_var.at(*u_var_offs),
                v_var.at(*v_var_offs),
                context=context,
            )

        yield CodeLine("", context=context)


class MatlabLibrary(Library):
    """MATLAB library in pure mode or MEX-wrapper mode."""

    BACKEND_IDENTIFIER = "matlab"
    FILEENDING = "m"
    INDENTSTR = "    "
    LIBROUTINE_CLASS = MatlabLibRoutine
    IMPORTLINE_CLASS = MLImportContainer
    DEFAULT_BUILDER = MatlabBuilder
    DEFAULT_CONTAINER_CLASS = MLRoutineContainer

    def __init__(
        self,
        plain_name,
        *,
        backend_builder=None,
        backend_library=None,
        build_hash=None,
        resource=None,
        configuration=None,
        general_configuration=None,
    ):
        backend_builder = MatlabBuilder.normalize_backend_builder(
            backend_builder
        )
        if resource is None:
            resource = MatlabComputeResource("MatlabResource")
        super().__init__(
            plain_name,
            build_hash=build_hash,
            resource=resource,
            configuration=configuration,
            general_configuration=general_configuration,
        )

        if backend_library is None:
            backend_library = MatlabBuilder.create_backend_library(
                plain_name,
                backend_builder=backend_builder,
                build_hash=build_hash,
            )

        self._backend_builder_class = backend_builder
        self._backend_library = backend_library
        if backend_library is not None:
            self._dependencies.add(backend_library)

    @property
    def is_wrapper_mode(self):
        return self._backend_library is not None

    @property
    def backend_library(self):
        return self._backend_library

    @property
    def backend_kind(self):
        return MatlabBuilder.identify_backend(self.backend_library)

    @property
    def mex_name(self):
        return self._get_mex_name()

    def _get_mex_name(self):
        return f"{self.libname}_mex"

    @property
    def gateway_source_name(self):
        return self._get_gateway_source_name()

    def _get_gateway_source_name(self):
        return f"{self.libname}_mex.c"

    @property
    def shim_source_name(self):
        return self._get_shim_source_name()

    def _get_shim_source_name(self):
        return f"{self.libname}_mex_shim.f90"

    @property
    def mex_target_name(self):
        return self._get_mex_target_name()

    def _get_mex_target_name(self):
        return f"mex_{self.libname}"

    def get_to_zero_support_routine(self, dtype):
        """Return the external helper routine used to reset one buffer."""
        routine_name = f"phoenix_to_zero_{dtype}"
        existing = self[routine_name]
        if existing is not None:
            return existing
        zero_value = MLLocalVariable(name="tmp", dtype=dtype, no_entry=True).get_zero_value()
        code = [
            f"function [buffer] = {routine_name}(buffer, size)",
            f"buffer(1:size) = {zero_value};",
            "end",
        ]
        return self._register_manual_routine(
            routine_name,
            code=code,
            arguments=[
                {
                    "name": "buffer",
                    "dtype": dtype,
                    "size": 1,
                    "status": "INOUT",
                    "assignment": ("buffer", "data"),
                },
                {
                    "name": "size",
                    "dtype": "i32",
                    "status": "IN",
                },
            ],
        )

    def _backend_source_libraries(self):
        if self.backend_library is None:
            return []
        dependencies = list(
            self.backend_library.get_dependencies(
                recursive=True,
                ignore_self=True,
            )
        )
        dependencies.reverse()
        return [*dependencies, self.backend_library]

    def _backend_source_files(self):
        return [
            library.filename for library in self._backend_source_libraries()
        ]

    def _detect_backend_builder(self, builder):
        if not self.is_wrapper_mode:
            backend_builder = MatlabBuilder.normalize_backend_builder(builder)
            if backend_builder is not None:
                raise ValueError(
                    "Pure MATLAB libraries do not accept a compiled backend builder"
                )
            return None

        backend_builder = builder
        if backend_builder is None:
            backend_builder = self._backend_builder_class
        backend_builder = MatlabBuilder.normalize_backend_builder(
            backend_builder
        )
        expected_kind = self.backend_kind
        actual_kind = MatlabBuilder.identify_backend(backend_builder)
        if actual_kind != expected_kind:
            raise ValueError(
                f"MATLAB library {self.libname} is bound to {expected_kind}, "
                f"but received routine builder {actual_kind}"
            )
        return backend_builder

    def prepare_sections(self, **kwargs):
        if self.backend_library is not None:
            self._dependencies.add(self.backend_library)
        return super().prepare_sections(**kwargs)

    def libroutine_from_instructions(
        self,
        name,
        *instructions,
        builder=None,
        daa_assignments=None,
        lrv_assignments=None,
        container_class=None,
        namespace=None,
        resource=None,
        **buildargs,
    ):
        backend_builder = self._detect_backend_builder(builder)
        if backend_builder is None:
            return super().libroutine_from_instructions(
                name,
                *instructions,
                builder=builder,
                daa_assignments=daa_assignments,
                lrv_assignments=lrv_assignments,
                container_class=container_class,
                namespace=namespace,
                resource=resource,
                **buildargs,
            )

        backend_routine = self.backend_library.libroutine_from_instructions(
            name,
            *instructions,
            builder=backend_builder(f"default:lib{name}"),
            daa_assignments=daa_assignments,
            lrv_assignments=lrv_assignments,
            container_class=container_class,
            namespace=namespace,
            resource=resource,
            **buildargs,
        )
        return self.create_libroutine_entry(
            name=name,
            arguments=list(backend_routine.get_arguments()),
            container=backend_routine.container,
            lrv_assignments=lrv_assignments,
            daa_assignments=daa_assignments,
            backend_routine=backend_routine,
        )

    def create_libroutine_entry(
        self,
        name,
        arguments,
        container,
        lrv_assignments,
        daa_assignments=None,
        backend_routine=None,
    ):
        libroutine = type(self).LIBROUTINE_CLASS(
            name,
            library=self,
            arguments=arguments,
            container=container,
            lrv_assignments=lrv_assignments,
            daa_assignments=daa_assignments,
            backend_routine=backend_routine,
        )
        self.append_libroutine(libroutine)
        return libroutine

    def _render_constant_properties(self, indent):
        constants = list(self.definition_capture.captured)
        if not constants:
            return
        yield indent, "properties(Constant)"
        for variable in constants:
            yield indent + 1, variable.get_property_definition()
        yield indent, "end"
        yield indent, ""

    def _render_scatter_helper(self, indent):
        yield indent, "function target = scatter_add(target, indices, values)"
        yield indent + 1, "indices = double(indices(:));"
        yield indent + 1, "values = values(:);"
        yield indent + 1, "if isscalar(values)"
        yield indent + 2, "values = repmat(values, numel(indices), 1);"
        yield indent + 1, "end"
        yield indent + 1, (
            "updates = accumarray(indices, double(values), [numel(target), 1], @sum, 0);"
        )
        yield indent + 1, "target = target + cast(updates, class(target));"
        yield indent, "end"

    def get_pure_codelines(self, indent=0):
        yield indent, "% autogenerated MATLAB library"
        imports = list(self.import_capture.list_imports())
        for library, routines in imports:
            names = ", ".join(routine.name for routine in routines)
            yield indent, f"% IMPORT {library.libname}: {names}"
        if imports:
            yield indent, ""
        yield indent, f"classdef {self.libname}"
        yield from self._render_constant_properties(indent + 1)
        yield indent + 1, "methods(Static)"
        yield from self._render_scatter_helper(indent + 2)
        if self.routine_containers:
            yield indent + 2, ""
        for num, routine_container in enumerate(self.routine_containers):
            yield from routine_container.get_codelines(indent=indent + 2)
            if num != len(self.routine_containers) - 1:
                yield indent + 2, ""
        yield indent + 1, "end"
        yield indent, "end"

    def _render_backend_comment_lines(self):
        importer = MLBackendImportContainer(
            self.backend_library, context=self.context
        )
        for indent, line in importer.get_codelines(indent=0):
            yield indent, line

    def _render_wrapper_method(self, routine, indent):
        yield indent, f"function varargout = {routine.name}(varargin)"
        yield indent + 1, f"{self.libname}.ensure_mex();"
        yield indent + 1, f"mex_name = {self.libname}.mex_name();"
        yield indent + 1, "if nargout > 0"
        yield (
            indent + 2,
            f"[varargout{{1:nargout}}] = feval(mex_name, '{routine.name}', varargin{{:}});",
        )
        yield indent + 1, "else"
        yield indent + 2, f"feval(mex_name, '{routine.name}', varargin{{:}});"
        yield indent + 1, "end"
        yield indent, "end"

    def _mex_source_names(self):
        if self.backend_kind == "FORTRAN":
            yield from self._backend_source_files()
            yield self.shim_source_name
            yield self.gateway_source_name
            return
        yield self.gateway_source_name
        yield from self._backend_source_files()

    def _matlab_sources_literal(self):
        entries = list(self._mex_source_names())
        return "{" + ", ".join(f"'{entry}'" for entry in entries) + "}"

    def _octave_build_command(self):
        source_parts = list(self._mex_source_names())
        quoted_sources = " ".join(f'\"{src}\"' for src in source_parts)
        return (
            f'mkoctfile --mex {quoted_sources} -I\"%s\" -o \"{self.mex_name}\"'
        )

    def _render_build_mex_method(self, indent):
        yield indent, "function build_mex()"
        yield indent + 1, "this_dir = fileparts(mfilename('fullpath'));"
        yield indent + 1, "source_names = " + self._matlab_sources_literal() + ";"
        yield indent + 1, (
            "sources = cellfun(@(name) fullfile(this_dir, name), "
            "source_names, 'UniformOutput', false);"
        )
        yield indent + 1, (
            f"mex_args = [{{'-output', '{self.mex_name}', ['-I' this_dir]}}, sources];"
        )
        yield indent + 1, "if exist('OCTAVE_VERSION', 'builtin') ~= 0"
        yield indent + 2, (
            f"cmd = sprintf('{self._octave_build_command()}', this_dir);"
        )
        yield indent + 2, "status = system(cmd);"
        yield indent + 2, "if status ~= 0"
        yield indent + 3, f"error('failed to build {self.mex_name} via mkoctfile');"
        yield indent + 2, "end"
        yield indent + 1, "else"
        yield indent + 2, "mex(mex_args{:});"
        yield indent + 1, "end"
        yield indent, "end"

    def _render_mex_name_method(self, indent):
        yield indent, "function name = mex_name()"
        yield indent + 1, f"name = '{self.mex_name}';"
        yield indent, "end"

    def _render_ensure_mex_method(self, indent):
        yield indent, "function ensure_mex()"
        yield indent + 1, "mex_name = " + f"{self.libname}.mex_name();"
        yield indent + 1, "if exist(mex_name, 'file') ~= 3"
        yield indent + 2, f"{self.libname}.build_mex();"
        yield indent + 1, "end"
        yield indent, "end"

    def get_wrapper_codelines(self, indent=0):
        yield indent, f"% MATLAB wrapper library for backend {self.backend_kind}"
        yield from self._render_backend_comment_lines()
        yield indent, f"classdef {self.libname}"
        yield indent + 1, "methods(Static)"
        for _name, routine in self.content:
            yield from self._render_wrapper_method(routine, indent + 2)
            yield indent + 2, ""
        yield from self._render_mex_name_method(indent + 2)
        yield indent + 2, ""
        yield from self._render_ensure_mex_method(indent + 2)
        yield indent + 2, ""
        yield from self._render_build_mex_method(indent + 2)
        yield indent + 1, "end"
        yield indent, "end"

    def get_codelines(self, indent=0):
        if self.is_wrapper_mode:
            yield from self.get_wrapper_codelines(indent=indent)
            return
        yield from self.get_pure_codelines(indent=indent)

    def _gateway_function_name(self, routine):
        return f"handle_{routine.name}"

    def _mx_class_id(self, dtype):
        lookup = {
            "f64": "mxDOUBLE_CLASS",
            "f32": "mxSINGLE_CLASS",
            "i32": "mxINT32_CLASS",
            "i64": "mxINT64_CLASS",
        }
        return lookup[dtype]

    def _c_dtype(self, dtype):
        lookup = {
            "f64": "double",
            "f32": "float",
            "i32": "int32_t",
            "i64": "int64_t",
        }
        return lookup[dtype]

    def _fortran_c_dtype(self, dtype):
        lookup = {
            "f64": "real(c_double)",
            "f32": "real(c_float)",
            "i32": "integer(c_int)",
            "i64": "integer(c_long_long)",
        }
        return lookup[dtype]

    def _prototype_arg(self, arg):
        ctype = self._c_dtype(arg.dtype)
        if self.backend_kind == "FORTRAN":
            return f"{ctype} *{arg.name}"
        if (arg.status & 3) == arg.STATUS_INPUT:
            if arg.is_scalar:
                return f"{ctype} {arg.name}"
            return f"const {ctype} *{arg.name}"
        return f"{ctype} *{arg.name}"

    def _prototype_name(self, routine):
        if self.backend_kind == "FORTRAN":
            return f"ml_{routine.name}"
        return routine.name

    def _iter_return_args(self, routine):
        for arg in routine.get_arguments():
            if arg.status & arg.STATUS_OUTPUT:
                yield arg

    def _iter_input_args(self, routine):
        for arg in routine.get_arguments():
            if arg.status & arg.STATUS_INPUT:
                yield arg

    def _render_gateway_prototypes(self):
        if self.backend_kind == "C":
            return
        for _name, routine in self.content:
            arg_string = ", ".join(
                self._prototype_arg(arg) for arg in routine.get_arguments()
            )
            yield f"void {self._prototype_name(routine)}({arg_string});"

    def _render_gateway_helpers(self):
        yield "static void mex_require_count(const char *routine, int got, int expected) {"
        yield '    if (got != expected) mexErrMsgIdAndTxt("phoenix:matlab:nrhs", "routine %s expects %d MATLAB input arguments but received %d", routine, expected, got);'
        yield "}"
        yield ""
        yield "static void mex_require_nlhs(const char *routine, int got, int expected) {"
        yield '    if (got > expected) mexErrMsgIdAndTxt("phoenix:matlab:nlhs", "routine %s produces at most %d outputs but %d were requested", routine, expected, got);'
        yield "}"
        yield ""
        yield "static void mex_check_numeric(const mxArray *arg, const char *routine, const char *name, mxClassID class_id, size_t expected_numel) {"
        yield "    if (!mxIsNumeric(arg) || mxGetClassID(arg) != class_id || mxIsComplex(arg)) {"
        yield '        mexErrMsgIdAndTxt("phoenix:matlab:type", "routine %s expects numeric argument %s with matching storage type", routine, name);'
        yield "    }"
        yield "    if (mxGetNumberOfElements(arg) != expected_numel) {"
        yield '        mexErrMsgIdAndTxt("phoenix:matlab:size", "routine %s expects %zu elements in %s", routine, expected_numel, name);'
        yield "    }"
        yield "}"

    def _render_gateway_handler(self, routine):
        input_args = list(self._iter_input_args(routine))
        return_args = list(self._iter_return_args(routine))
        yield f"static void {self._gateway_function_name(routine)}(int nlhs, mxArray *plhs[], int nrhs, const mxArray *prhs[]) {{"
        yield (
            f'    mex_require_count("{routine.name}", nrhs, {len(input_args)});'
        )
        yield (
            f'    mex_require_nlhs("{routine.name}", nlhs, {len(return_args)});'
        )
        yield ""
        input_index = 0
        output_index = 0
        call_args = []
        for arg in routine.get_arguments():
            ctype = self._c_dtype(arg.dtype)
            numel = arg.size if arg.size is not None else 1
            status = arg.status & 3
            if status == arg.STATUS_INPUT:
                yield (
                    f'    mex_check_numeric(prhs[{input_index}], "{routine.name}", "{arg.name}", {self._mx_class_id(arg.dtype)}, {numel});'
                )
                if arg.is_scalar and self.backend_kind == "C":
                    call_args.append(
                        f"*(({ctype} *)mxGetData((mxArray *)prhs[{input_index}]))"
                    )
                else:
                    call_args.append(
                        f"({ctype} *)mxGetData((mxArray *)prhs[{input_index}])"
                    )
                input_index += 1
                continue

            if status == arg.STATUS_INOUT:
                yield (
                    f'    mex_check_numeric(prhs[{input_index}], "{routine.name}", "{arg.name}", {self._mx_class_id(arg.dtype)}, {numel});'
                )
                yield f"    plhs[{output_index}] = mxDuplicateArray(prhs[{input_index}]);"
                call_args.append(
                    f"({ctype} *)mxGetData(plhs[{output_index}])"
                )
                input_index += 1
                output_index += 1
                continue

            yield (
                f"    plhs[{output_index}] = mxCreateNumericMatrix({numel}, 1, {self._mx_class_id(arg.dtype)}, mxREAL);"
            )
            call_args.append(f"({ctype} *)mxGetData(plhs[{output_index}])")
            output_index += 1

        call_name = self._prototype_name(routine)
        yield ""
        yield f"    {call_name}({', '.join(call_args)});"
        yield "}"

    def get_gateway_lines(self):
        yield "#include \"mex.h\""
        yield "#include <stdint.h>"
        yield "#include <string.h>"
        if self.backend_kind == "C":
            yield f'#include "{self.backend_library.headername}"'
        yield ""
        yield "#ifdef __cplusplus"
        yield 'extern "C" {'
        yield "#endif"
        yield from self._render_gateway_prototypes()
        yield "#ifdef __cplusplus"
        yield "}"
        yield "#endif"
        yield ""
        yield from self._render_gateway_helpers()
        yield ""
        for _name, routine in self.content:
            yield from self._render_gateway_handler(routine)
            yield ""
        yield "void mexFunction(int nlhs, mxArray *plhs[], int nrhs, const mxArray *prhs[]) {"
        yield "    char routine_name[256];"
        yield '    if (nrhs < 1 || !mxIsChar(prhs[0])) mexErrMsgIdAndTxt("phoenix:matlab:dispatch", "first argument must be the routine name string");'
        yield (
            "    if (mxGetString(prhs[0], routine_name, sizeof(routine_name)) != 0) "
            'mexErrMsgIdAndTxt("phoenix:matlab:dispatch", "failed to read routine name");'
        )
        for index, (_name, routine) in enumerate(self.content):
            keyword = "if" if index == 0 else "else if"
            yield (
                f'    {keyword} (strcmp(routine_name, "{routine.name}") == 0) '
                f'{{ {self._gateway_function_name(routine)}(nlhs, plhs, nrhs - 1, prhs + 1); return; }}'
            )
        yield '    mexErrMsgIdAndTxt("phoenix:matlab:dispatch", "unknown routine %s", routine_name);'
        yield "}"

    def write_gateway_source(self):
        with open(self.gateway_source_name, "w") as file:
            for line in self.get_gateway_lines():
                file.write(line + "\n")

    def _render_fortran_shim_arg(self, arg):
        dtype = self._fortran_c_dtype(arg.dtype)
        intent_lookup = {
            arg.STATUS_INPUT: "in",
            arg.STATUS_OUTPUT: "out",
            arg.STATUS_INOUT: "inout",
        }
        intent = intent_lookup[arg.status & 3]
        if arg.is_scalar:
            return f"{dtype}, intent({intent}) :: {arg.name}"
        return f"{dtype}, intent({intent}) :: {arg.name}({arg.size})"

    def get_fortran_shim_lines(self):
        for _name, routine in self.content:
            yield (
                f"subroutine ml_{routine.name}("
                + ", ".join(arg.name for arg in routine.get_arguments())
                + f') bind(C, name="ml_{routine.name}")'
            )
            yield "    use iso_c_binding"
            yield f"    use {self.backend_library.libname}, only: {routine.name}"
            yield "    implicit none"
            for arg in routine.get_arguments():
                yield "    " + self._render_fortran_shim_arg(arg)
            yield (
                f"    call {routine.name}("
                + ", ".join(arg.name for arg in routine.get_arguments())
                + ")"
            )
            yield f"end subroutine ml_{routine.name}"
            yield ""

    def write_fortran_shim(self):
        if self.backend_kind != "FORTRAN":
            return
        with open(self.shim_source_name, "w") as file:
            for line in self.get_fortran_shim_lines():
                file.write(line + "\n")

    def write_all_files(self):
        self.write_code()
        if self.is_wrapper_mode:
            self.write_gateway_source()
            self.write_fortran_shim()
        self.write_docs()
        return True

    def build(self, makefile=None, force=False, compile=True):
        if self.backend_library is not None:
            self.backend_library.build(
                makefile=makefile, force=force, compile=compile
            )
        return super().build(makefile=makefile, force=force, compile=compile)

    def _mex_target_dependencies(self):
        yield MFTSource(self.gateway_source_name)
        if self.backend_kind == "FORTRAN":
            yield MFTSource(self.shim_source_name)
        for library in self._backend_source_libraries():
            code_target = library.get_codefile_target()
            if code_target is not None:
                yield code_target
            header_target = library.get_header_target()
            if header_target is not None:
                yield header_target

    def _makefile_mex_command(self):
        sources = list(self._mex_source_names())
        quoted = " ".join(f'"{src}"' for src in sources)
        return (
            f'if command -v mex >/dev/null 2>&1; then mex -output "{self.mex_name}" -I. {quoted}; '
            f'elif command -v mkoctfile >/dev/null 2>&1; then mkoctfile --mex {quoted} -I. -o "{self.mex_name}"; '
            'else echo "Neither mex nor mkoctfile found"; exit 1; fi'
        )

    def get_library_target(self):
        if not self.is_wrapper_mode:
            return None
        return MFTSpecial(
            self.mex_target_name,
            dependencies=list(self._mex_target_dependencies()),
            commands=[self._makefile_mex_command()],
        )

    def get_makefile_targets(self):
        if self.backend_library is not None:
            yield from self.backend_library.get_makefile_targets()
        yield self.get_codefile_target()
        if self.is_wrapper_mode:
            yield MFTSource(self.gateway_source_name)
            if self.backend_kind == "FORTRAN":
                yield MFTSource(self.shim_source_name)
            yield self.get_library_target()


MatlabBuilder.set_instruction_class_handler(
    AffineOperationInstruction, MatlabBuilder.handle_affine_instruction
)
MatlabBuilder.set_instruction_class_handler(
    BiLinearOperationInstruction, MatlabBuilder.handle_bilinear_instruction
)

MLRoutineContainer.set_comment_class(MLCommentLine)

MatlabBuilder.set_comment_class(MLCommentLine)
MatlabBuilder.set_routinecall_class(MLRoutineCallContainer)
